}"}, "type": "tool_use", "display_intent": "Review EBS volume configuration in us-east-1"}, {"id": "tooluse_IWiAMobxJhDplS88hk5Vfp", "tool_name": "subagent", "input": {"name": "ebs-backup-review", "agent_type": "generic", "prompt": "{
